const seq = [{ move_to: 400 }, { move_to: 0 }];
const i = context.get('step') || 0;
context.set('step', (i + 1) % seq.length);
msg.payload = seq[i];
return msg;

if (msg.payload.fault) {
    node.warn('TMC5160 fault bitmask: ' + msg.payload.fault);
    return msg;
}
if (msg.payload.tstep !== undefined && msg.payload.sg_result < 100) {
    node.warn('TMC5160 SG_RESULT low: ' + msg.payload.sg_result);
    return msg;
}
return null;
